package com.resolvenow.assignment;
import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import jakarta.validation.constraints.Email; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.NotNull; import jakarta.validation.constraints.Size; import java.util.*;
@RestController @RequestMapping("/assignments") public class AssignmentController { private final AssignmentService service; public AssignmentController(AssignmentService service){this.service=service;} public record Request(@NotNull Long complaintId,@NotBlank @Email String customerEmail,@Size(max=100) String department,@Size(max=100) String agent){} @GetMapping public List<Assignment> all(){return service.all();} @PostMapping public Assignment assign(@Valid @RequestBody Request request){return service.assign(request.complaintId(),request.customerEmail(),request.department()==null?"Customer Service":request.department(),request.agent()==null?"Unassigned":request.agent());} }
